 var main=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1,Margin=Padding.Empty};main.RowStyles.Add(new RowStyle(SizeType.Percent,100));main.RowStyles.Add(new RowStyle(SizeType.Absolute,58));shell.Controls.Add(main,1,1);body=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(28,24,28,24),Margin=Padding.Empty};main.Controls.Add(body,0,0);notice=new Label{Text="Videira Site • Catálogo conectado à loja online",Dock=DockStyle.Fill,Padding=new Padding(20,12,20,0),BackColor=Color.White};main.Controls.Add(notice,0,1);}
 FlowLayoutPanel PageRoot(string heading){body.Controls.Clear();var root=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};body.Controls.Add(root);root.Controls.Add(new Label{Text=heading,Font=new Font("Segoe UI",23),ForeColor=Color.FromArgb(29,35,39),AutoSize=true,Margin=new Padding(0,0,0,22)});root.SizeChanged+=(s,e)=>{};body.Resize+=(s,e)=>{if(!root.IsDisposed)foreach(Control c in root.Controls)if(!(c is Label))c.Width=Math.Max(780,body.ClientSize.Width-60);};root.Width=Math.Max(780,body.ClientSize.Width-60);return root;}
 Panel Card(string heading,int height){var card=new Panel{Width=Math.Max(780,body.ClientSize.Width-60),Height=height,BackColor=Color.White,BorderStyle=BorderStyle.FixedSingle,Margin=new Padding(0,0,0,20),Padding=new Padding(20)};card.Controls.Add(new Label{Text=heading,Font=new Font("Segoe UI",12,FontStyle.Bold),AutoSize=true,Location=new Point(20,18)});return card;}
 void ShowPage(string name){page=name;foreach(var n in nav)n.Value.BackColor=n.Key==name?blue:dark;if(!api.Connected&&!preview){LoginPage();return;}if(name=="Painel")Dashboard();else if(name=="Produtos")ProductsPage();else if(name=="Adicionar produto")Editor(null);else if(name=="Categorias")CategoriesPage();else if(name=="Mídia")MediaPage();else SettingsPage();}
 void LoginPage(){var root=PageRoot("Bem-vindo à Videira");var c=Card("Acesse o painel do site",290);root.Controls.Add(c);c.Controls.Add(new Label{Text="E-mail",AutoSize=true,Location=new Point(20,60)});var email=new TextBox{Text=SiteApi.AdminEmail,ReadOnly=true,Location=new Point(20,86),Width=380};c.Controls.Add(email);c.Controls.Add(new Label{Text="Senha",AutoSize=true,Location=new Point(20,124)});var pass=new TextBox{UseSystemPasswordChar=true,Location=new Point(20,150),Width=380};c.Controls.Add(pass);var button=ActionButton("Entrar",async()=>{string secret=pass.Text;pass.Clear();await api.Login(SiteApi.AdminEmail,secret);await Reload();account.Text=SiteApi.AdminEmail;ShowPage("Painel");Notify("Conectado. As alterações são gravadas no catálogo do site.");},true);button.Location=new Point(20,198);c.Controls.Add(button);var text=new Label{Text="Use a mesma conta e senha do seu catálogo.\nO painel do site funciona separado do VIDEIRA GESTÃO.",Location=new Point(450,85),Size=new Size(420,70),ForeColor=Color.DimGray};c.Controls.Add(text);}
 async Task Reload(){products=await api.Products();var rows=(object[])await api.Request("/rest/v1/product_categories?select=name&order=name.asc");categories=rows.Cast<Dictionary<string,object>>().Select(r=>SiteApi.Read(r,"name")).Concat(products.Select(p=>SiteApi.Read(p,"category"))).Where(x=>x!="").Distinct().OrderBy(x=>x).ToList();}
 void Dashboard(){var root=PageRoot("Painel");var tiles=new TableLayoutPanel{Width=root.Width,Height=600,ColumnCount=2,RowCount=2,Margin=Padding.Empty};tiles.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));tiles.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));tiles.RowStyles.Add(new RowStyle(SizeType.Percent,50));tiles.RowStyles.Add(new RowStyle(SizeType.Percent,50));root.Controls.Add(tiles);var stats=Card("Visão geral",260);stats.Dock=DockStyle.Fill;stats.Margin=new Padding(0,0,20,20);tiles.Controls.Add(stats,0,0);stats.Controls.Add(new Label{Text=products.Count+" produtos\n"+products.Count(p=>Convert.ToBoolean(p["active"]))+" publicados\n"+categories.Count+" categorias",Location=new Point(20,62),Size=new Size(380,110),ForeColor=blue,Font=new Font("Segoe UI",14)});stats.Controls.Add(new Label{Text="Videira Vinhoteca • Catálogo online",Location=new Point(20,208),AutoSize=true,ForeColor=Color.DimGray});var draft=Card("Rascunho rápido de produto",260);draft.Dock=DockStyle.Fill;draft.Margin=new Padding(0,0,0,20);tiles.Controls.Add(draft,1,0);var quickTitle=Input(draft,"Nome do produto",20,53,350);var quickText=Input(draft,"Descrição",20,115,350);var save=ActionButton("Salvar rascunho",async()=>{if(quickTitle.Text.Trim()=="")throw new Exception("Informe o nome do produto.");await api.Save(new Dictionary<string,object>{{"name",quickTitle.Text.Trim()},{"description",quickText.Text.Trim()},{"category","Outro"},{"active",false},{"featured",false},{"price",null}},"");dirty=false;await Reload();Dashboard();Notify("Rascunho salvo no site. Ele fica oculto até você publicar.");},true);save.Location=new Point(20,197);draft.Controls.Add(save);var recent=Card("Atividade recente",280);recent.Dock=DockStyle.Fill;recent.Margin=new Padding(0,0,20,0);tiles.Controls.Add(recent,0,1);recent.Controls.Add(new Label{Text=products.Count==0?"Nenhum produto cadastrado.\nAdicione seu primeiro vinho.":String.Join("\n",products.Take(5).Select(p=>SiteApi.Read(p,"name")+" — "+(Convert.ToBoolean(p["active"])?"Publicado":"Rascunho"))),Location=new Point(20,63),Size=new Size(380,150)});var help=Card("Seu catálogo, organizado",280);help.Dock=DockStyle.Fill;help.Margin=Padding.Empty;tiles.Controls.Add(help,1,1);help.Controls.Add(new Label{Text="Produtos: preços, descrições e publicação.\n\nCategorias: organização e renomeação.\n\nMídia: fotos associadas aos vinhos.\n\nConfigurações: contato da loja.",Location=new Point(20,63),Size=new Size(400,175),ForeColor=Color.DimGray});dirty=false;}
 DataGridView Grid(){var g=new DataGridView{ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,MultiSelect=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,RowHeadersVisible=false,BackgroundColor=Color.White,BorderStyle=BorderStyle.FixedSingle,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,EnableHeadersVisualStyles=false,ColumnHeadersHeight=38};g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(246,247,247);g.ColumnHeadersDefaultCellStyle.ForeColor=Color.FromArgb(44,51,56);g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(227,241,248);g.DefaultCellStyle.SelectionForeColor=Color.FromArgb(0,90,140);g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(249,249,249);g.GridColor=Color.FromArgb(230,230,230);g.RowTemplate.Height=38;return g;}
 void ProductsPage(){var root=PageRoot("Produtos");var toolbar=new FlowLayoutPanel{Height=50};var search=new TextBox{Width=230,Margin=new Padding(0,4,12,0)};toolbar.Controls.Add(search);var status=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=135,Margin=new Padding(0,4,12,0)};status.Items.AddRange(new object[]{"Todos","Publicados","Rascunhos"});status.SelectedIndex=0;toolbar.Controls.Add(status);toolbar.Controls.Add(ActionButton("Adicionar novo",()=>{Editor(null);return Task.FromResult(0);},true));toolbar.Controls.Add(ActionButton("Atualizar",async()=>{await Reload();ProductsPage();Notify("Lista atualizada do site.");}));root.Controls.Add(toolbar);var grid=Grid();grid.Width=root.Width;grid.Height=430;root.Controls.Add(grid);Action render=()=>{grid.DataSource=products.Where(p=>String.Join(" ",new[]{SiteApi.Read(p,"name"),SiteApi.Read(p,"category"),SiteApi.Read(p,"country"),SiteApi.Read(p,"grape")}).IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0).Where(p=>status.SelectedIndex==0||Convert.ToBoolean(p["active"])==(status.SelectedIndex==1)).Select(p=>new ProductRow{Id=SiteApi.Read(p,"id"),Produto=SiteApi.Read(p,"name"),Categoria=SiteApi.Read(p,"category"),Preço=p["price"]==null?"Sob consulta":Convert.ToDecimal(p["price"]).ToString("N2"),Situação=Convert.ToBoolean(p["active"])?"Publicado":"Rascunho"}).ToList();grid.Columns["Id"].Visible=false;grid.Columns["Produto"].FillWeight=250;};render();search.TextChanged+=(s,e)=>render();status.SelectedIndexChanged+=(s,e)=>render();Func<Dictionary<string,object>> selected=()=>grid.CurrentRow==null?null:products.FirstOrDefault(p=>SiteApi.Read(p,"id")==((ProductRow)grid.CurrentRow.DataBoundItem).Id);grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0)Editor(selected());};var actions=new FlowLayoutPanel{Height=50};actions.Controls.Add(ActionButton("Editar produto",()=>{var p=selected();if(p==null)throw new Exception("Selecione um produto.");Editor(p);return Task.FromResult(0);}));actions.Controls.Add(ActionButton("Mover para rascunho",async()=>{var p=selected();if(p==null)throw new Exception("Selecione um produto.");await api.Hide(SiteApi.Read(p,"id"));await Reload();ProductsPage();Notify("Produto retirado da vitrine e mantido como rascunho.");}));root.Controls.Add(actions);}
 TextBox Input(Panel card,string label,int x,int y,int width,string value="",bool multiline=false){card.Controls.Add(new Label{Text=label,Location=new Point(x,y),AutoSize=true});var t=new TextBox{Text=value,Location=new Point(x,y+25),Size=new Size(width,multiline?110:28),Multiline=multiline,MaxLength=multiline?5000:200};t.TextChanged+=(s,e)=>dirty=true;card.Controls.Add(t);return t;}
 void Editor(Dictionary<string,object> product){editing=product==null?"":SiteApi.Read(product,"id");Func<string,string> v=k=>product==null?"":SiteApi.Read(product,k);var root=PageRoot(editing==""?"Adicionar produto":"Editar produto");var main=Card("Dados do produto",580);root.Controls.Add(main);title=Input(main,"Nome do produto *",20,60,700,v("name"));price=Input(main,"Preço (R$) — vazio significa sob consulta",20,130,330,product==null||product["price"]==null?"":Convert.ToDecimal(product["price"]).ToString("0.00",CultureInfo.GetCultureInfo("pt-BR")));main.Controls.Add(new Label{Text="Categoria *",Location=new Point(390,130),AutoSize=true});category=new ComboBox{Location=new Point(390,155),Width=330,DropDownStyle=ComboBoxStyle.DropDown};category.Items.AddRange(categories.Cast<object>().ToArray());category.Text=v("category");category.TextChanged+=(s,e)=>dirty=true;main.Controls.Add(category);country=Input(main,"País",20,200,330,v("country"));grape=Input(main,"Uva",390,200,330,v("grape"));winery=Input(main,"Bodega / produtor",20,270,700,v("winery"));description=Input(main,"Descrição",20,340,700,v("description"),true);
 var publish=Card("Publicar",145);root.Controls.Add(publish);published=new CheckBox{Text="Publicado na loja",Checked=product!=null&&Convert.ToBoolean(product["active"]),Location=new Point(20,57),AutoSize=true};featured=new CheckBox{Text="Destaque na página inicial",Checked=product!=null&&Convert.ToBoolean(product["featured"]),Location=new Point(250,57),AutoSize=true};published.CheckedChanged+=(s,e)=>dirty=true;featured.CheckedChanged+=(s,e)=>dirty=true;publish.Controls.Add(published);publish.Controls.Add(featured);var save=ActionButton(editing==""?"Salvar produto":"Atualizar produto",Save,true);save.Location=new Point(20,96);publish.Controls.Add(save);
 var media=Card("Imagem do produto",175);root.Controls.Add(media);photo=Input(media,"URL HTTPS da foto",20,54,700,v("image_url"));photo.MaxLength=2000;var upload=ActionButton("Selecionar e enviar imagem",async()=>{using(var d=new OpenFileDialog{Filter="Fotos|*.jpg;*.jpeg;*.png;*.webp"}){if(d.ShowDialog()!=DialogResult.OK)return;photo.Text=await api.UploadPhoto(d.FileName);Notify("Imagem enviada. Salve o produto para associar a foto.");}});upload.Location=new Point(20,122);media.Controls.Add(upload);dirty=false;}
 async Task Save(){if(title.Text.Trim()==""||category.Text.Trim()=="")throw new Exception("Preencha nome e categoria.");decimal number;object amount=null;if(price.Text.Trim()!=""){if(!Decimal.TryParse(price.Text.Trim().Replace('.',','),NumberStyles.AllowDecimalPoint,CultureInfo.GetCultureInfo("pt-BR"),out number)||number<0||number>9999999999m)throw new Exception("Informe um preço válido.");amount=Math.Round(number,2);}Uri u;if(photo.Text.Trim()!=""&&(!Uri.TryCreate(photo.Text.Trim(),UriKind.Absolute,out u)||u.Scheme!="https"))throw new Exception("Informe uma URL HTTPS válida para a foto.");string cat=category.Text.Trim();if(cat.Length>100)throw new Exception("Categoria deve ter até 100 caracteres.");if(!categories.Contains(cat))await api.Request("/rest/v1/product_categories","POST",new{name=cat});await api.Save(new Dictionary<string,object>{{"name",title.Text.Trim()},{"category",cat},{"price",amount},{"country",country.Text.Trim()},{"grape",grape.Text.Trim()},{"winery",winery.Text.Trim()},{"description",description.Text.Trim()},{"image_url",photo.Text.Trim()},{"active",published.Checked},{"featured",featured.Checked}},editing);dirty=false;await Reload();ProductsPage();Notify("Produto salvo no site. Atualize a loja no navegador para ver as alterações.");}
 void CategoriesPage(){var root=PageRoot("Categorias de produtos");var card=Card("Adicionar ou editar categoria",190);root.Controls.Add(card);var name=Input(card,"Nome da categoria",20,55,380);dirty=false;name.TextChanged+=(s,e)=>dirty=false;string selected="";var add=ActionButton("Adicionar categoria",async()=>{if(name.Text.Trim()==""||name.Text.Trim().Length>100)throw new Exception("Informe um nome de até 100 caracteres.");await api.Request("/rest/v1/product_categories","POST",new{name=name.Text.Trim()});await Reload();CategoriesPage();Notify("Categoria criada no site.");},true);add.Location=new Point(20,120);card.Controls.Add(add);var rename=ActionButton("Renomear selecionada",async()=>{if(selected==""||name.Text.Trim()=="")throw new Exception("Selecione uma categoria e informe o novo nome.");await api.Request("/rest/v1/rpc/rename_product_category","POST",new{old_name=selected,new_name=name.Text.Trim()});await Reload();CategoriesPage();Notify("Categoria e produtos vinculados atualizados no site.");});rename.Location=new Point(200,120);card.Controls.Add(rename);var grid=Grid();grid.Width=root.Width;grid.Height=380;grid.DataSource=categories.Select(c=>new CategoryRow{Nome=c,Produtos=products.Count(p=>SiteApi.Read(p,"category")==c)}).ToList();grid.SelectionChanged+=(s,e)=>{if(grid.CurrentRow==null)return;selected=((CategoryRow)grid.CurrentRow.DataBoundItem).Nome;name.Text=selected;};grid.CellClick+=(s,e)=>{if(e.RowIndex<0)return;selected=((CategoryRow)grid.Rows[e.RowIndex].DataBoundItem).Nome;name.Text=selected;};root.Controls.Add(grid);}
 void MediaPage(){var root=PageRoot("Biblioteca de mídia");var info=Card("Imagens do catálogo",110);info.Controls.Add(new Label{Text="Envie fotos pelo editor de produto. JPG, PNG ou WebP até 6 MB.\nEsta lista mostra as imagens associadas aos produtos.",Location=new Point(20,52),Size=new Size(700,48)});root.Controls.Add(info);var grid=Grid();grid.Width=root.Width;grid.Height=450;grid.DataSource=products.Where(p=>SiteApi.Read(p,"image_url")!="").Select(p=>new MediaRow{Produto=SiteApi.Read(p,"name"),Imagem=SiteApi.Read(p,"image_url")}).ToList();grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex<0)return;var r=(MediaRow)grid.Rows[e.RowIndex].DataBoundItem;Editor(products.First(p=>SiteApi.Read(p,"name")==r.Produto&&SiteApi.Read(p,"image_url")==r.Imagem));};root.Controls.Add(grid);}
 void SettingsPage(){var root=PageRoot("Configurações");var card=Card("Contato da loja",210);root.Controls.Add(card);var phone=Input(card,"WhatsApp com código do país e DDD",20,60,380);dirty=false;phone.TextChanged+=(s,e)=>dirty=false;var button=ActionButton("Salvar alterações",async()=>{string n=new string(phone.Text.Where(Char.IsDigit).ToArray());if(n.Length<10||n.Length>15)throw new Exception("Informe o número com país e DDD.");var rows=(object[])await api.Request("/rest/v1/store_settings?id=eq.true","PATCH",new{whatsapp=n});if(rows.Length!=1)throw new Exception("O servidor não confirmou o contato.");Notify("Contato atualizado no site.");},true);button.Location=new Point(20,132);card.Controls.Add(button);if(api.Connected)BeginInvoke(new Action(async()=>await Run(async()=>{var rows=(object[])await api.Request("/rest/v1/store_settings?select=whatsapp");if(!phone.IsDisposed&&rows.Length>0)phone.Text=SiteApi.Read((Dictionary<string,object>)rows[0],"whatsapp");})));}
 public void SavePreview(string path){using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(path);}}
 [STAThread] public static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);CultureInfo.DefaultThreadCurrentCulture=CultureInfo.GetCultureInfo("pt-BR");bool check=args.Contains("--self-test");bool demo=args.Contains("--preview")||check;using(var app=new VideiraSite(demo)){if(demo)app.Shown+=(s,e)=>{var timer=new Timer{Interval=600};timer.Tick+=(a,b)=>{timer.Stop();if(check){try{app.ProductsPage();app.Editor(null);app.CategoriesPage();app.MediaPage();app.SettingsPage();app.dirty=false;app.Dashboard();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ui-check.txt"),"PASS: painel, lista de produtos, editor, categorias, mídia e configurações renderizados.");}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ui-check.txt"),"FAIL: "+ex.ToString());}}app.SavePreview(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"videira-site-preview.png"));app.Close();};timer.Start();};Application.Run(app);}}
}
